i clients</button></form><form method="post" action="<?= base_url('its-network-action/' . $device['id']) ?>" onsubmit="return confirm('Reboot this MikroTik router? Network service will be interrupted.')"><?= csrf_field() ?><input type="hidden" name="action" value="reboot"><input type="hidden" name="confirm_action" value="REBOOT"><button class="btn danger">Reboot</button></form><?php } elseif (str_contains($maker, 'hikvision') && $device['device_type'] === 'nvr') { ?><form method="post" action="<?= base_url('its-network-action/' . $device['id']) ?>" onsubmit="return confirm('Request Hikvision NVR storage status?')"><?= csrf_field() ?><input type="hidden" name="action" value="storage"><button class="btn secondary">Storage</button></form><form method="post" action="<?= base_url('its-network-action/' . $device['id']) ?>" onsubmit="return confirm('Reboot this Hikvision NVR? Recording will be interrupted.')"><?= csrf_field() ?><input type="hidden" name="action" value="reboot"><input type="hidden" name="confirm_action" value="REBOOT"><button class="btn danger">Reboot</button></form><?php } } ?><form method="post" action="<?= base_url('its-network-devices-delete/' . $device['id']) ?>" onsubmit="return confirm('Delete this device?')"><?= csrf_field() ?><button class="btn danger">Delete</button></form></div></td></tr><?php } ?></tbody></table></div><?php } else { ?><p class="muted">No network devices registered yet.</p><?php } ?>
